            return 0;
        }
        if (upper == 1) {
            lower = 0;
        }
        while (k < 13) {
            while (m >= PmRn[k * 3 + 0]) {
                emon.Port.CellsPush(@out, PmRn[k * 3 + 1] + lower);
                if (PmRn[k * 3 + 2] != 0) {
                    emon.Port.CellsPush(@out, PmRn[k * 3 + 2] + lower);
                }
                m -= PmRn[k * 3 + 0];
            }
            k += 1;
        }
        return 0;
    }
