                    cur = emon.Port.CellsAt(nt, ln - 3);
                    parent = emon.Port.CellsAt(nt, ln - 2);
                    depth = emon.Port.CellsAt(nt, ln - 1);
                    emon.Port.CellsDrop(nt, ln - 3);
                }
            } else {
                item = Pdfdoc.PdResolve(src, ar, dc, a, b, st, cur);
                num = 0;
                if (Pdflex.PlKindOf(ar, cur) == 9) {
                    num = Pdflex.PlIntValue(ar, cur);
                }
                nxt = 0;
                if ((item == 0) || (Pdflex.PlKindOf(ar, item) != 7)) {
                    cur = 0;
                } else if (Pdfx.PxSeenMark(seen, num) == 1) {
                    if (parent >= 0) {
                        emon.Port.CellsSet(ol, (parent * OlStride) + 21, emon.Port.CellsAt(ol, (parent * OlStride) + 21) | 4);
                    }
                    cur = 0;
                } else if ((emon.Port.CellsLen(ol) / OlStride) >= PmOlMax) {
                    done = 1;
                } else {
                    row = PmOlNew(ol, depth, parent, num);
                    PmOlFill(src, ar, dc, a, b, st, idx, pg, txt, ol, row, item);
                    nxt = Pdfx.PxGet(ar, item, Pdfxnames.PxNext());
                    fst = Pdflex.PlDictGet(ar, item, Pdfnames.PnFirst());
                    if ((fst != 0) && ((depth + 1) < PmDepth)) {
                        emon.Port.CellsPush(nt, nxt);
                        emon.Port.CellsPush(nt, parent);
                        emon.Port.CellsPush(nt, depth);
                        parent = row;
                        depth += 1;
                        cur = fst;
                    } else {
                        if (fst != 0) {
                            emon.Port.CellsSet(ol, (row * OlStride) + 21, emon.Port.CellsAt(ol, (row * OlStride) + 21) | 8);
                        }
                        cur = nxt;
                    }
                }
            }
        }
        // Subtree sizes: children follow their parent, so one backward pass.
        n = emon.Port.CellsLen(ol) / OlStride;
        k = n - 1;
        while (k >= 0) {
            p = emon.Port.CellsAt(ol, (k * OlStride) + 1);
            if (p >= 0) {
                sz = emon.Port.CellsAt(ol, (k * OlStride) + 3);
                emon.Port.CellsSet(ol, (p * OlStride) + 3, emon.Port.CellsAt(ol, (p * OlStride) + 3) + sz);
            }
            k -= 1;
        }
        return n;
    }
    internal static int PmXEq(emon.Port.Cells w, int s, int n, int id) {
        // 1 when w[s, s+n) spells row `id` of the xs table.
        int o = Pdfxnames.XsSpan[id * 2 + 0];
        int m = Pdfxnames.XsSpan[id * 2 + 1];
        int i = 0;
        if (n != m) {
            return 0;
        }
        while (i < n) {
            if (emon.Port.CellsAt(w, s + i) != Pdfxnames.XsChars[o + i]) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
    internal static int PmXSame(emon.Port.Cells w, int s1, int s2, int n) {
        int i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(w, s1 + i) != emon.Port.CellsAt(w, s2 + i)) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
    internal static int PmXColon(emon.Port.Cells w, int s, int n) {
        // The offset of the first `:` in the name w[s, s+n), -1 when there is none.
        int i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(w, s + i) == 58) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int PmXUriId(emon.Port.Cells nt, emon.Port.Cells w, int ps, int pl) {
        // The xs id (0..6) of the namespace the prefix w[ps, ps+pl) is declared to be, -1
        // when it is undeclared or is a namespace emon has no name for. The newest
        // declaration wins.
        int i = emon.Port.CellsAt(nt, 0) - 1;
        int at = 0;
        int k = 0;
        while (i >= 0) {
            at = NtNs + (i * 4);
            if (emon.Port.CellsAt(nt, at + 1) == pl) {
                if (PmXSame(w, emon.Port.CellsAt(nt, at), ps, pl) == 1) {
                    k = 0;
                    while (k < 7) {
                        if (PmXEq(w, emon.Port.CellsAt(nt, at + 2), emon.Port.CellsAt(nt, at + 3), k) == 1) {
                            return k;
                        }
                        k += 1;
                    }
                    return -1;
                }
            }
            i -= 1;
        }
        return -1;
    }
    internal static int PmXLocalId(emon.Port.Cells w, int s, int n) {
        // The xs id of a local name, -1 when it is not one the reader knows.
        int rows = 46;
        int k = 7;
        while (k < rows) {
            if (PmXEq(w, s, n, k) == 1) {
                return k;
            }
            k += 1;
        }
        return -1;
    }
    internal static int PmXClassify(emon.Port.Cells nt, emon.Port.Cells w, int s, int n) {
        // A qualified name as one integer: ((namespace id + 1) * 1024) + (local id + 1),
        // a part that is unknown counting as 0.
        int c = PmXColon(w, s, n);
        int uri = -1;
        int loc = -1;
        if (c < 0) {
            uri = PmXUriId(nt, w, s, 0);
            loc = PmXLocalId(w, s, n);
        } else {
            uri = PmXUriId(nt, w, s, c);
            loc = PmXLocalId(w, (s + c) + 1, (n - c) - 1);
        }
        return ((uri + 1) * 1024) + (loc + 1);
    }
    internal static int PmXKnown(int uri, int loc) {
        // The `xk` of a property: namespace id and local id to the property emon reads.
        if (uri == Pdfxnames.XsNsDc()) {
            if (loc == Pdfxnames.XsTitle()) {
                return 1;
            }
            if (loc == Pdfxnames.XsCreator()) {
                return 2;
            }
            if (loc == Pdfxnames.XsDescriptionL()) {
                return 3;
            }
            if (loc == Pdfxnames.XsSubject()) {
                return 4;
            }
            if (loc == Pdfxnames.XsLanguage()) {
                return 5;
            }
            if (loc == Pdfxnames.XsFormat()) {
                return 6;
            }
            if (loc == Pdfxnames.XsRights()) {
                return 7;
            }
            if (loc == Pdfxnames.XsPublisher()) {
                return 8;
            }
            if (loc == Pdfxnames.XsIdentifier()) {
                return 24;
            }
            if (loc == Pdfxnames.XsDate()) {
                return 25;
            }
        }
        if (uri == Pdfxnames.XsNsPdf()) {
            if (loc == Pdfxnames.XsProducer()) {
                return 9;
            }
            if (loc == Pdfxnames.XsKeywords()) {
                return 10;
            }
            if (loc == Pdfxnames.XsPdfVersion()) {
                return 11;
            }
        }
        if (uri == Pdfxnames.XsNsXmp()) {
            if (loc == Pdfxnames.XsCreatorTool()) {
                return 12;
            }
            if (loc == Pdfxnames.XsCreateDate()) {
                return 13;
            }
            if (loc == Pdfxnames.XsModifyDate()) {
                return 14;
            }
            if (loc == Pdfxnames.XsMetadataDate()) {
                return 15;
            }
        }
        if (uri == Pdfxnames.XsNsXmpMm()) {
            if (loc == Pdfxnames.XsDocumentId()) {
                return 16;
            }
            if (loc == Pdfxnames.XsInstanceId()) {
                return 17;
            }
            if (loc == Pdfxnames.XsOriginalDocumentId()) {
                return 18;
            }
        }
        if (uri == Pdfxnames.XsNsPdfuaid()) {
            if (loc == Pdfxnames.XsPart()) {
                return 19;
            }
            if (loc == Pdfxnames.XsRev()) {
                return 20;
            }
        }
        if (uri == Pdfxnames.XsNsPdfaid()) {
            if (loc == Pdfxnames.XsPart()) {
                return 21;
            }
            if (loc == Pdfxnames.XsConformance()) {
                return 22;
            }
            if (loc == Pdfxnames.XsAmd()) {
                return 23;
            }
        }
        return 0;
    }
    internal static int PmXIsWs(int c) {
        if (c == 32) {
            return 1;
        }
        if (c == 10) {
            return 1;
        }
        if (c == 13) {
            return 1;
        }
        if (c == 9) {
            return 1;
        }
        return 0;
    }
    internal static int PmXSeqLen(emon.Port.Cells w, int i, int to) {
        // The length of the well-formed UTF-8 sequence at w[i], 1 when it is not one.
        int c = emon.Port.CellsAt(w, i);
        int need = 0;
        int cp = 0;
        int lo = 0;
        int j = 1;
        if ((c >= 194) && (c <= 223)) {
            need = 1;
            cp = c - 192;
            lo = 128;
        }
        if ((c >= 224) && (c <= 239)) {
            need = 2;
            cp = c - 224;
            lo = 2048;
        }
        if ((c >= 240) && (c <= 244)) {
            need = 3;
            cp = c - 240;
            lo = 65536;
        }
        if (need == 0) {
            return 1;
        }
        if (((i + need) + 1) > to) {
            return 1;
        }
        while (j <= need) {
            if ((emon.Port.CellsAt(w, i + j) & 192) != 128) {
                return 1;
            }
            cp = (cp * 64) + (emon.Port.CellsAt(w, i + j) & 63);
            j += 1;
        }
        if (cp < lo) {
            return 1;
        }
        if (cp > 1114111) {
            return 1;
        }
        if ((cp >= 55296) && (cp <= 57343)) {
            return 1;
        }
        return need + 1;
    }
    internal static int PmXSeqCp(emon.Port.Cells w, int i, int ln) {
        int c = emon.Port.CellsAt(w, i);
        int cp = 0;
        int j = 1;
        if (ln == 1) {
            return c;
        }
        if (ln == 2) {
            cp = c - 192;
        }
        if (ln == 3) {
            cp = c - 224;
        }
        if (ln == 4) {
            cp = c - 240;
        }
        while (j < ln) {
            cp = (cp * 64) + (emon.Port.CellsAt(w, i + j) & 63);
            j += 1;
        }
        return cp;
    }
    internal static int PmXEntity(emon.Port.Cells w, int i, int to, emon.Port.Cells txt) {
        // An entity at w[i] (`&`): pushes its code point and answers the position after the
        // `;`; answers -1 and pushes nothing when it is not one of the five, `&#N;` or `&#xH;`.
        int j = i + 1;
        int semi = -1;
        int k = 0;
        int v = 0;
        int c = 0;
        int d = 0;
        int n = 0;
        int hex = 0;
        while ((j < to) && (j < (i + 12)) && (semi == -1)) {
            if (emon.Port.CellsAt(w, j) == 59) {
                semi = j;
            }
            j += 1;
        }
        if (semi == -1) {
            return -1;
        }
        n = (semi - i) - 1;
        c = emon.Port.CellsAt(w, i + 1);
        if ((n == 3) && (c == 97) && (emon.Port.CellsAt(w, i + 2) == 109) && (emon.Port.CellsAt(w, i + 3) == 112)) {
            Pdfx.PxPushCp(txt, 38);
            return semi + 1;
        }
        if ((n == 2) && (c == 108) && (emon.Port.CellsAt(w, i + 2) == 116)) {
            Pdfx.PxPushCp(txt, 60);
            return semi + 1;
        }
        if ((n == 2) && (c == 103) && (emon.Port.CellsAt(w, i + 2) == 116)) {
            Pdfx.PxPushCp(txt, 62);
            return semi + 1;
        }
        if ((n == 4) && (c == 113) && (emon.Port.CellsAt(w, i + 2) == 117) && (emon.Port.CellsAt(w, i + 3) == 111) && (emon.Port.CellsAt(w, i + 4) == 116)) {
            Pdfx.PxPushCp(txt, 34);
            return semi + 1;
        }
        if ((n == 4) && (c == 97) && (emon.Port.CellsAt(w, i + 2) == 112) && (emon.Port.CellsAt(w, i + 3) == 111) && (emon.Port.CellsAt(w, i + 4) == 115)) {
            Pdfx.PxPushCp(txt, 39);
            return semi + 1;
        }
        if ((c == 35) && (n > 1)) {
            k = i + 2;
            if ((emon.Port.CellsAt(w, k) == 120) || (emon.Port.CellsAt(w, k) == 88)) {
                hex = 1;
                k += 1;
            }
            if (k >= semi) {
                return -1;
            }
            while (k < semi) {
                d = emon.Port.CellsAt(w, k);
                if ((d >= 48) && (d <= 57)) {
                    d -= 48;
                } else if ((hex == 1) && (d >= 97) && (d <= 102)) {
                    d -= 87;
                } else if ((hex == 1) && (d >= 65) && (d <= 70)) {
                    d -= 55;
                } else {
                    return -1;
                }
                if (hex == 1) {
                    v = (v * 16) + d;
                } else {
                    v = (v * 10) + d;
                }
                if (v > 1114111) {
                    return -1;
                }
                k += 1;
            }
            Pdfx.PxPushCp(txt, v);
            return semi + 1;
        }
        return -1;
    }
    internal static int PmXText(emon.Port.Cells w, int from, int to, int ent, emon.Port.Cells txt) {
        // w[from, to) as text into `txt`: UTF-8 (a byte that is not part of a sequence is
        // Latin-1), entities decoded when `ent` is 1.
        int i = from;
        int c = 0;
        int ln = 0;
        int r = 0;
        while (i < to) {
            c = emon.Port.CellsAt(w, i);
            r = -1;
            if ((c == 38) && (ent == 1)) {
                r = PmXEntity(w, i, to, txt);
            }
            if (r >= 0) {
                i = r;
            } else {
                ln = PmXSeqLen(w, i, to);
                Pdfx.PxPushCp(txt, PmXSeqCp(w, i, ln));
                i += ln;
            }
        }
        return 0;
    }
    internal static int PmXTagEnd(emon.Port.Cells w, int i, int n) {
        // Where the tag whose attributes start at `i` ends: the `>` outside any quotes.
        int p = i;
        int q = 0;
        int c = 0;
        while (p < n) {
            c = emon.Port.CellsAt(w, p);
            if (q == 0) {
                if ((c == 34) || (c == 39)) {
                    q = c;
                }
                if (c == 62) {
                    return p;
                }
            } else if (c == q) {
                q = 0;
            }
            p += 1;
        }
        return n;
    }
    internal static int PmXAttr(emon.Port.Cells nt, emon.Port.Cells w, int p, int e) {
        // The next attribute in w[p, e): its name and value spans go to nt[4..8) (name
        // start, length, value start, length) and the position after it is answered; -1
        // when there is none.
        int i = p;
        int ns = 0;
        int nl = 0;
        int vs = 0;
        int vl = 0;
        int q = 0;
        int c = 0;
        while ((i < e) && (PmXIsWs(emon.Port.CellsAt(w, i)) == 1)) {
            i += 1;
        }
        if (i >= e) {
            return -1;
        }
        c = emon.Port.CellsAt(w, i);
        if ((c == 47) || (c == 62)) {
            return -1;
        }
        ns = i;
        while ((i < e) && (PmXIsWs(emon.Port.CellsAt(w, i)) == 0) && (emon.Port.CellsAt(w, i) != 61) && (emon.Port.CellsAt(w, i) != 47) && (emon.Port.CellsAt(w, i) != 62)) {
            i += 1;
        }
        nl = i - ns;
        while ((i < e) && (PmXIsWs(emon.Port.CellsAt(w, i)) == 1)) {
            i += 1;
        }
        if ((i < e) && (emon.Port.CellsAt(w, i) == 61)) {
            i += 1;
            while ((i < e) && (PmXIsWs(emon.Port.CellsAt(w, i)) == 1)) {
                i += 1;
            }
            if (i < e) {
                q = emon.Port.CellsAt(w, i);
            }
            if ((q == 34) || (q == 39)) {
                i += 1;
                vs = i;
                while ((i < e) && (emon.Port.CellsAt(w, i) != q)) {
                    i += 1;
                }
                vl = i - vs;
                if (i < e) {
                    i += 1;
                }
            } else {
                vs = i;
                while ((i < e) && (PmXIsWs(emon.Port.CellsAt(w, i)) == 0) && (emon.Port.CellsAt(w, i) != 62)) {
                    i += 1;
                }
                vl = i - vs;
            }
        } else {
            vs = i;
        }
        if (i == p) {
            i = p + 1;
        }
        emon.Port.CellsSet(nt, 4, ns);
        emon.Port.CellsSet(nt, 5, nl);
        emon.Port.CellsSet(nt, 6, vs);
        emon.Port.CellsSet(nt, 7, vl);
        return i;
    }
    internal static int PmRunInt(emon.Port.Cells txt, int s, int n) {
        // The decimal number a run spells (surrounding white space allowed), -1 otherwise.
        int i = 0;
        int v = 0;
        int c = 0;
        int got = 0;
        while (i < n) {
            c = emon.Port.CellsAt(txt, s + i);
            if ((c >= 48) && (c <= 57)) {
                v = (v * 10) + (c - 48);
                got = 1;
                if (v > 100000000) {
                    return -1;
                }
            } else if (PmXIsWs(c) != 1) {
                return -1;
            }
            i += 1;
        }
        if (got == 0) {
            return -1;
        }
        return v;
    }
    internal static int PmXRow(emon.Port.Cells xm, emon.Port.Cells txt, emon.Port.Cells md, emon.Port.Cells w, int ns, int nl0, int kind, int vs, int vl, int ls, int ll, int known) {
        // Append an XMP property row; the name is copied into `txt` from w[ns, ns+nl); the
        // value and language are runs already there. Sets the header cells of the properties
        // emon reads into `md` (PDF/UA and PDF/A identification).
        int s = emon.Port.CellsLen(txt);
        int nl = nl0;
        int v = 0;
        PmXText(w, ns, ns + nl0, 0, txt);
        nl = emon.Port.CellsLen(txt) - s;
        emon.Port.CellsPush(xm, s);
        emon.Port.CellsPush(xm, nl);
        emon.Port.CellsPush(xm, kind);
        emon.Port.CellsPush(xm, vs);
        emon.Port.CellsPush(xm, vl);
        emon.Port.CellsPush(xm, ls);
        emon.Port.CellsPush(xm, ll);
        emon.Port.CellsPush(xm, known);
        emon.Port.CellsPush(xm, 0);
        emon.Port.CellsPush(xm, 0);
        v = emon.Port.CellsAt(md, 46);
        emon.Port.CellsSet(md, 46, v + 1);
        if ((known == 19) && (emon.Port.CellsAt(md, 42) == -1)) {
            v = PmRunInt(txt, vs, vl);
            emon.Port.CellsSet(md, 42, v);
        }
        if ((known == 20) && (emon.Port.CellsAt(md, 59) == -1)) {
            v = PmRunInt(txt, vs, vl);
            emon.Port.CellsSet(md, 59, v);
        }
        if ((known == 21) && (emon.Port.CellsAt(md, 43) == -1)) {
            v = PmRunInt(txt, vs, vl);
            emon.Port.CellsSet(md, 43, v);
        }
        if ((known == 22) && (emon.Port.CellsAt(md, 44) == -1)) {
            emon.Port.CellsSet(md, 44, vs);
            emon.Port.CellsSet(md, 45, vl);
        }
        return 0;
    }
    internal static int PmXPop(emon.Port.Cells nt, emon.Port.Cells w, emon.Port.Cells txt, emon.Port.Cells md, emon.Port.Cells xm) {
        // Close the innermost element. A property element or an `rdf:li` that had no child
        // elements is a value: its row is written. Answers 0.
        int d = emon.Port.CellsAt(nt, 1);
        int fo = 0;
        int role = 0;
        int pf = 0;
        int vs = 0;
        int vl = 0;
        int cl = 0;
        int known = 0;
        int kind = 0;
        if (d <= 0) {
            return 0;
        }
        fo = NtStack + ((d - 1) * FrStride);
        role = emon.Port.CellsAt(nt, fo + 2);
        if ((emon.Port.CellsAt(nt, fo + 3) == 0) && ((role == 2) || (role == 4))) {
            vs = emon.Port.CellsAt(nt, fo + 4);
            vl = emon.Port.CellsLen(txt) - vs;
            if (role == 2) {
                cl = PmXClassify(nt, w, emon.Port.CellsAt(nt, fo), emon.Port.CellsAt(nt, fo + 1));
                known = PmXKnown((cl / 1024) - 1, (cl % 1024) - 1);
                PmXRow(xm, txt, md, w, emon.Port.CellsAt(nt, fo), emon.Port.CellsAt(nt, fo + 1), 0, vs, vl, -1, 0, known);
            }
            if ((role == 4) && (d >= 3)) {
                pf = fo - (2 * FrStride);
                cl = PmXClassify(nt, w, emon.Port.CellsAt(nt, pf), emon.Port.CellsAt(nt, pf + 1));
                known = PmXKnown((cl / 1024) - 1, (cl % 1024) - 1);
                kind = emon.Port.CellsAt(nt, (fo - FrStride) + 7);
                PmXRow(xm, txt, md, w, emon.Port.CellsAt(nt, pf), emon.Port.CellsAt(nt, pf + 1), kind, vs, vl, emon.Port.CellsAt(nt, fo + 5), emon.Port.CellsAt(nt, fo + 6), known);
            }
        }
        emon.Port.CellsSet(nt, 1, d - 1);
        return 0;
    }
    internal static int PmXmpScan(emon.Port.Cells w, emon.Port.Cells nt, emon.Port.Cells txt, emon.Port.Cells md, emon.Port.Cells xm) {
        // Read the XMP packet in `w` (bytes) into `xm` rows and the header cells of `md`.
        // `nt` is scratch (namespaces, the open elements). Answers 1, or 2 when it is UTF-16
        // (not read) and no row was written.
        emon.Port.CellsDrop(nt, 0);
        int n = emon.Port.CellsLen(w);
        int i = 0;
        int k = 0;
        int c = 0;
        int c1 = 0;
        int j = 0;
        int d = 0;
        int fo = 0;
        int role = 0;
        int prole = 0;
        int ck = 0;
        int ns = 0;
        int nl = 0;
        int gt = 0;
        int selfc = 0;
        int cl = 0;
        int uri = 0;
        int loc = 0;
        int p = 0;
        int @as = 0;
        int al = 0;
        int av = 0;
        int avl = 0;
        int nn = 0;
        int at = 0;
        int vs = 0;
        int cl2 = 0;
        int colon = 0;
        int langs = -1;
        int langl = 0;
        int skip = 0;
        while (k < NtSize) {
            emon.Port.CellsPush(nt, 0);
            k += 1;
        }
        if (n > PmXmp) {
            n = PmXmp;
        }
        if (n >= 2) {
            if (((emon.Port.CellsAt(w, 0) == 254) && (emon.Port.CellsAt(w, 1) == 255)) || ((emon.Port.CellsAt(w, 0) == 255) && (emon.Port.CellsAt(w, 1) == 254))) {
                return 2;
            }
        }
        if (n >= 3) {
            if ((emon.Port.CellsAt(w, 0) == 239) && (emon.Port.CellsAt(w, 1) == 187) && (emon.Port.CellsAt(w, 2) == 191)) {
                i = 3;
            }
        }
        while (i < n) {
            c = emon.Port.CellsAt(w, i);
            if (c != 60) {
                j = i;
                while ((j < n) && (emon.Port.CellsAt(w, j) != 60)) {
                    j += 1;
                }
                d = emon.Port.CellsAt(nt, 1);
                if (d > 0) {
                    fo = NtStack + ((d - 1) * FrStride);
                    role = emon.Port.CellsAt(nt, fo + 2);
                    if (((role == 2) || (role == 4)) && (emon.Port.CellsAt(nt, fo + 3) == 0)) {
                        PmXText(w, i, j, 1, txt);
                    }
                }
                i = j;
            } else {
                c1 = 0;
                if ((i + 1) < n) {
                    c1 = emon.Port.CellsAt(w, i + 1);
                }
                if (c1 == 63) {
                    j = i + 2;
                    while (((j + 1) < n) && ((emon.Port.CellsAt(w, j) != 63) || (emon.Port.CellsAt(w, j + 1) != 62))) {
                        j += 1;
                    }
                    i = j + 2;
                } else if (c1 == 33) {
                    if (((i + 3) < n) && (emon.Port.CellsAt(w, i + 2) == 45) && (emon.Port.CellsAt(w, i + 3) == 45)) {
                        j = i + 4;
                        while (((j + 2) < n) && ((emon.Port.CellsAt(w, j) != 45) || (emon.Port.CellsAt(w, j + 1) != 45) || (emon.Port.CellsAt(w, j + 2) != 62))) {
                            j += 1;
                        }
                        i = j + 3;
                    } else if (((i + 8) < n) && (emon.Port.CellsAt(w, i + 2) == 91) && (emon.Port.CellsAt(w, i + 3) == 67) && (emon.Port.CellsAt(w, i + 4) == 68) && (emon.Port.CellsAt(w, i + 5) == 65) && (emon.Port.CellsAt(w, i + 6) == 84) && (emon.Port.CellsAt(w, i + 7) == 65) && (emon.Port.CellsAt(w, i + 8) == 91)) {
                        j = i + 9;
                        while (((j + 2) < n) && ((emon.Port.CellsAt(w, j) != 93) || (emon.Port.CellsAt(w, j + 1) != 93) || (emon.Port.CellsAt(w, j + 2) != 62))) {
                            j += 1;
                        }
                        d = emon.Port.CellsAt(nt, 1);
                        if (d > 0) {
                            fo = NtStack + ((d - 1) * FrStride);
                            role = emon.Port.CellsAt(nt, fo + 2);
                            if (((role == 2) || (role == 4)) && (emon.Port.CellsAt(nt, fo + 3) == 0)) {
                                PmXText(w, i + 9, j, 0, txt);
                            }
                        }
                        i = j + 3;
                    } else {
                        j = PmXTagEnd(w, i + 2, n);
                        i = j + 1;
                    }
                } else if (c1 == 47) {
                    j = i + 2;
                    while ((j < n) && (emon.Port.CellsAt(w, j) != 62)) {
                        j += 1;
                    }
                    PmXPop(nt, w, txt, md, xm);
                    i = j + 1;
                } else {
                    // A start tag: the name, the namespaces it declares, then its role.
                    ns = i + 1;
                    j = ns;
                    while ((j < n) && (PmXIsWs(emon.Port.CellsAt(w, j)) == 0) && (emon.Port.CellsAt(w, j) != 47) && (emon.Port.CellsAt(w, j) != 62)) {
                        j += 1;
                    }
                    nl = j - ns;
                    gt = PmXTagEnd(w, j, n);
                    selfc = 0;
                    if ((gt > j) && (emon.Port.CellsAt(w, gt - 1) == 47)) {
                        selfc = 1;
                    }
                    p = j;
                    while (p >= 0) {
                        p = PmXAttr(nt, w, p, gt);
                        if (p >= 0) {
                            @as = emon.Port.CellsAt(nt, 4);
                            al = emon.Port.CellsAt(nt, 5);
                            if ((al >= 5) && (PmXEq(w, @as, 5, Pdfxnames.XsXmlns()) == 1)) {
                                nn = emon.Port.CellsAt(nt, 0);
                                if ((nn < 64) && ((al == 5) || (emon.Port.CellsAt(w, @as + 5) == 58))) {
                                    at = NtNs + (nn * 4);
                                    if (al == 5) {
                                        emon.Port.CellsSet(nt, at, @as);
                                        emon.Port.CellsSet(nt, at + 1, 0);
                                    } else {
                                        emon.Port.CellsSet(nt, at, @as + 6);
                                        emon.Port.CellsSet(nt, at + 1, al - 6);
                                    }
                                    emon.Port.CellsSet(nt, at + 2, emon.Port.CellsAt(nt, 6));
                                    emon.Port.CellsSet(nt, at + 3, emon.Port.CellsAt(nt, 7));
                                    emon.Port.CellsSet(nt, 0, nn + 1);
                                }
                            }
                        }
                    }
                    d = emon.Port.CellsAt(nt, 1);
                    if (d >= 46) {
                        i = n;
                    } else {
                        prole = 0;
                        if (d > 0) {
                            prole = emon.Port.CellsAt(nt, (NtStack + ((d - 1) * FrStride)) + 2);
                        }
                        cl = PmXClassify(nt, w, ns, nl);
                        uri = (cl / 1024) - 1;
                        loc = (cl % 1024) - 1;
                        role = 0;
                        ck = 0;
                        if ((uri == Pdfxnames.XsNsRdf()) && (loc == Pdfxnames.XsRdf())) {
                            role = 6;
                        }
                        if ((uri == Pdfxnames.XsNsRdf()) && (loc == Pdfxnames.XsDescription()) && ((prole == 6) || (d == 0))) {
                            role = 1;
                        }
                        if ((role == 0) && (prole == 1) && (uri != Pdfxnames.XsNsRdf())) {
                            role = 2;
                        }
                        if ((role == 0) && (prole == 2) && (uri == Pdfxnames.XsNsRdf())) {
                            if (loc == Pdfxnames.XsSeq()) {
                                role = 3;
                                ck = 1;
                            }
                            if (loc == Pdfxnames.XsBag()) {
                                role = 3;
                                ck = 2;
                            }
                            if (loc == Pdfxnames.XsAlt()) {
                                role = 3;
                                ck = 3;
                            }
                        }
                        if ((role == 0) && (prole == 3) && (uri == Pdfxnames.XsNsRdf()) && (loc == Pdfxnames.XsLi())) {
                            role = 4;
                        }
                        // The parent now has a child element: any text it had is white space.
                        if (d > 0) {
                            fo = NtStack + ((d - 1) * FrStride);
                            if (((prole == 2) || (prole == 4)) && (emon.Port.CellsAt(nt, fo + 3) == 0)) {
                                emon.Port.CellsSet(nt, fo + 3, 1);
                                emon.Port.CellsDrop(txt, emon.Port.CellsAt(nt, fo + 4));
                            }
                        }
                        langs = -1;
                        langl = 0;
                        p = j;
                        while (p >= 0) {
                            p = PmXAttr(nt, w, p, gt);
                            if (p >= 0) {
                                @as = emon.Port.CellsAt(nt, 4);
                                al = emon.Port.CellsAt(nt, 5);
                                av = emon.Port.CellsAt(nt, 6);
                                avl = emon.Port.CellsAt(nt, 7);
                                colon = PmXColon(w, @as, al);
                                if (role == 1) {
                                    skip = 0;
                                    if ((al >= 5) && (PmXEq(w, @as, 5, Pdfxnames.XsXmlns()) == 1)) {
                                        skip = 1;
                                    }
                                    if (colon < 0) {
                                        skip = 1;
                                    }
                                    if ((colon == 3) && (PmXEq(w, @as, 3, Pdfxnames.XsXml()) == 1)) {
                                        skip = 1;
                                    }
                                    cl2 = PmXClassify(nt, w, @as, al);
                                    if (((cl2 / 1024) - 1) == Pdfxnames.XsNsRdf()) {
                                        skip = 1;
                                    }
                                    if (skip == 0) {
                                        vs = emon.Port.CellsLen(txt);
                                        PmXText(w, av, av + avl, 1, txt);
                                        PmXRow(xm, txt, md, w, @as, al, 4, vs, emon.Port.CellsLen(txt) - vs, -1, 0, PmXKnown((cl2 / 1024) - 1, (cl2 % 1024) - 1));
                                    }
                                }
                                if ((role == 4) && (colon == 3)) {
                                    if ((PmXEq(w, @as, 3, Pdfxnames.XsXml()) == 1) && (PmXEq(w, @as + 4, al - 4, Pdfxnames.XsLang()) == 1)) {
                                        langs = emon.Port.CellsLen(txt);
                                        PmXText(w, av, av + avl, 1, txt);
                                        langl = emon.Port.CellsLen(txt) - langs;
                                    }
                                }
                            }
                        }
                        fo = NtStack + (d * FrStride);
                        emon.Port.CellsSet(nt, fo, ns);
                        emon.Port.CellsSet(nt, fo + 1, nl);
                        emon.Port.CellsSet(nt, fo + 2, role);
                        emon.Port.CellsSet(nt, fo + 3, 0);
                        emon.Port.CellsSet(nt, fo + 4, emon.Port.CellsLen(txt));
                        emon.Port.CellsSet(nt, fo + 5, langs);
                        emon.Port.CellsSet(nt, fo + 6, langl);
                        emon.Port.CellsSet(nt, fo + 7, ck);
                        emon.Port.CellsSet(nt, 1, d + 1);
                        if (selfc == 1) {
                            PmXPop(nt, w, txt, md, xm);
                        }
                        i = gt + 1;
                    }
                }
            }
        }
        return 1;
    }
    internal static int PmMdInit(emon.Port.Cells md) {
        // The header of `md`: zero, with the runs, the dates and the tri-state flags absent.
        emon.Port.CellsDrop(md, 0);
        int k = 0;
        while (k < MdSize) {
            emon.Port.CellsPush(md, 0);
            k += 1;
        }
        k = 0;
        while (k < 20) {
            emon.Port.CellsSet(md, k, -1);
            k += 2;
        }
        k = 20;
        while (k < 34) {
            emon.Port.CellsSet(md, k, -1);
            k += 1;
        }
        emon.Port.CellsSet(md, 35, -1);
        emon.Port.CellsSet(md, 38, -1);
        emon.Port.CellsSet(md, 39, -1);
        emon.Port.CellsSet(md, 40, -1);
        emon.Port.CellsSet(md, 42, -1);
        emon.Port.CellsSet(md, 43, -1);
        emon.Port.CellsSet(md, 44, -1);
        emon.Port.CellsSet(md, 50, -1);
        emon.Port.CellsSet(md, 57, -1);
        emon.Port.CellsSet(md, 59, -1);
        return 0;
    }
    internal static int PmBoolOf(emon.Port.Cells ar, int h) {
        // 1 or 0 for a boolean object, -1 for anything else (or absent).
        if (h == 0) {
            return -1;
        }
        if (Pdflex.PlKindOf(ar, h) == 1) {
            return Pdflex.PlIntValue(ar, h);
        }
        return -1;
    }
    internal static int PmInfo(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells md) {
        // The Info dictionary into the header of `md`.
        int ih = Pdfdoc.PdTrailerGet(ar, dc, Pdfnames.PnInfo());
        int info = Pdfdoc.PdResolve(src, ar, dc, a, b, st, ih);
        int v = 0;
        if (info == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, info) != 7) {
            return 0;
        }
        emon.Port.CellsSet(md, 34, 1);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnTitle());
        Pdfannot.PaTextTo(txt, ar, v, md, 2);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnAuthor());
        Pdfannot.PaTextTo(txt, ar, v, md, 4);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnSubject());
        Pdfannot.PaTextTo(txt, ar, v, md, 6);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnKeywords());
        Pdfannot.PaTextTo(txt, ar, v, md, 8);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnCreator());
        Pdfannot.PaTextTo(txt, ar, v, md, 10);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnProducer());
        Pdfannot.PaTextTo(txt, ar, v, md, 12);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnCreationDate());
        Pdfannot.PaTextTo(txt, ar, v, md, 14);
        if (emon.Port.CellsAt(md, 14) >= 0) {
            Pdfx.PxDateParse(txt, emon.Port.CellsAt(md, 14), emon.Port.CellsAt(md, 15), md, 20);
        }
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, info, Pdfnames.PnModDate());
        Pdfannot.PaTextTo(txt, ar, v, md, 16);
        if (emon.Port.CellsAt(md, 16) >= 0) {
            Pdfx.PxDateParse(txt, emon.Port.CellsAt(md, 16), emon.Port.CellsAt(md, 17), md, 27);
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, info, Pdfxnames.PxTrapped());
        Pdfannot.PaTextTo(txt, ar, v, md, 18);
        return 0;
    }
    internal static int PmCatalog(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells md, int root) {
        // /Lang, /Version, /MarkInfo, the presence of the structure tree, forms, outlines,
        // labels, permissions, and the viewer preference that says to show the title.
        int v = 0;
        int af = 0;
        int vp = 0;
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnLang());
        Pdfannot.PaTextTo(txt, ar, v, md, 0);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnVersion());
        Pdfannot.PaTextTo(txt, ar, v, md, 50);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnMarkInfo());
        if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 7)) {
            vp = Pdfdoc.PdDget(src, ar, dc, a, b, st, v, Pdfnames.PnMarked());
            emon.Port.CellsSet(md, 35, PmBoolOf(ar, vp));
        }
        if (Pdflex.PlDictGet(ar, root, Pdfnames.PnStructTreeRoot()) != 0) {
            emon.Port.CellsSet(md, 36, 1);
        }
        af = Pdfdoc.PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnAcroForm());
        if ((af != 0) && (Pdflex.PlKindOf(ar, af) == 7)) {
            emon.Port.CellsSet(md, 37, 1);
            v = Pdfx.PxDget(src, ar, dc, a, b, st, af, Pdfxnames.PxNeedAppearances());
            emon.Port.CellsSet(md, 38, PmBoolOf(ar, v));
            v = Pdfx.PxDget(src, ar, dc, a, b, st, af, Pdfxnames.PxSigFlags());
            if (Pdfx.PxIsNum(ar, v) == 1) {
                emon.Port.CellsSet(md, 39, Pdfx.PxIntOf(ar, v, -1));
            }
            if (Pdfx.PxGet(ar, af, Pdfxnames.PxXfa()) != 0) {
                emon.Port.CellsSet(md, 53, 1);
            }
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, root, Pdfxnames.PxViewerPreferences());
        if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 7)) {
            vp = Pdfx.PxDget(src, ar, dc, a, b, st, v, Pdfxnames.PxDisplayDocTitle());
            emon.Port.CellsSet(md, 40, PmBoolOf(ar, vp));
        }
        if (Pdflex.PlDictGet(ar, root, Pdfnames.PnOutlines()) != 0) {
            emon.Port.CellsSet(md, 47, 1);
        }
        if (Pdflex.PlDictGet(ar, root, Pdfnames.PnPageLabels()) != 0) {
            emon.Port.CellsSet(md, 48, 1);
        }
        if (Pdfx.PxGet(ar, root, Pdfxnames.PxPerms()) != 0) {
            emon.Port.CellsSet(md, 52, 1);
        }
        return 0;
    }
    internal static int PmDests(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells pg, emon.Port.Cells txt, emon.Port.Cells nt, emon.Port.Cells nd) {
        // Every named destination (the old /Dests dictionary first, then the name tree)
        // into `nd`, at most PM_ND_MAX.
        emon.Port.CellsDrop(nd, 0);
        int n = Pdfx.PxDestsCollect(src, ar, dc, a, b, st, idx, nt);
        int i = 0;
        int at = 0;
        int k = 0;
        int key = 0;
        int val = 0;
        if (n > PmNdMax) {
            n = PmNdMax;
        }
        while (i < n) {
            at = emon.Port.CellsLen(nd);
            k = 0;
            while (k < NdStride) {
                emon.Port.CellsPush(nd, 0);
                k += 1;
            }
            key = emon.Port.CellsAt(nt, i * 2);
            val = emon.Port.CellsAt(nt, (i * 2) + 1);
            Pdfannot.PaTextTo(txt, ar, key, nd, at);
            Pdfx.PxDestOf(src, ar, dc, a, b, st, idx, pg, txt, val, nd, at + 2);
            if (Pdfsrc.PsMissed(src)) {
                return -1;
            }
            i += 1;
        }
        return n;
    }
    public static int PmRun(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells idx, emon.Port.Cells txt, emon.Port.Cells w, emon.Port.Cells seen, emon.Port.Cells md, emon.Port.Cells xm, emon.Port.Cells ol, emon.Port.Cells lb, emon.Port.Cells nd, emon.Port.Cells nt) {
        // Everything P3.9 reads, after `pd-open`, `pd-pages` and `px-index-build`. `md xm ol
        // lb nd` are the results and are cleared first; `txt` is APPENDED to; `w` and `nt` are
        // scratch (the decoded XMP packet; stacks and pairs); `seen` a visited set. Answers
        // the number of outline rows, or -1 when the source missed (re-run on a fresh view).
        PmMdInit(md);
        emon.Port.CellsDrop(xm, 0);
        emon.Port.CellsDrop(ol, 0);
        emon.Port.CellsDrop(lb, 0);
        emon.Port.CellsDrop(nd, 0);
        int root = Pdfdoc.PdRoot(dc);
        int npages = Pdfdoc.PdPgCount(pg);
        int mh = 0;
        int xs = 0;
        int rows = 0;
        int nl = 0;
        int nn = 0;
        int k = 0;
        int dp = 0;
        PmInfo(src, ar, dc, a, b, st, txt, md);
        PmCatalog(src, ar, dc, a, b, st, txt, md, root);
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        mh = Pdfdoc.PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnMetadata());
        if ((mh != 0) && (Pdflex.PlKindOf(ar, mh) == 8)) {
            Pdfdoc.PdStreamData(src, ar, dc, a, b, st, mh, w);
            if (Pdfsrc.PsMissed(src)) {
                return -1;
            }
            if (emon.Port.CellsLen(w) > 0) {
                xs = PmXmpScan(w, nt, txt, md, xm);
                emon.Port.CellsSet(md, 41, xs);
            } else {
                emon.Port.CellsSet(md, 41, 2);
            }
        }
        rows = PmOutlines(src, ar, dc, a, b, st, idx, pg, txt, seen, nt, ol, root);
        if (rows < 0) {
            return -1;
        }
        emon.Port.CellsSet(md, 55, rows);
        k = 0;
        while (k < rows) {
            dp = emon.Port.CellsAt(ol, k * OlStride) + 1;
            if (dp > emon.Port.CellsAt(md, 56)) {
                emon.Port.CellsSet(md, 56, dp);
            }
            k += 1;
        }
        nl = PmLabels(src, ar, dc, a, b, st, idx, txt, nt, lb, root, npages);
        emon.Port.CellsSet(md, 54, nl);
        if ((emon.Port.CellsAt(idx, 1) != 0) || (emon.Port.CellsAt(idx, 2) != 0)) {
            emon.Port.CellsSet(md, 49, 1);
            nn = PmDests(src, ar, dc, a, b, st, idx, pg, txt, nt, nd);
            if (nn < 0) {
                return -1;
            }
            emon.Port.CellsSet(md, 57, nn);
        }
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        return rows;
    }
    internal static int PmJRun(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells md, int at) {
        return Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(md, at), emon.Port.CellsAt(md, at + 1));
    }
    internal static int PmJDate(System.Text.StringBuilder t, emon.Port.Cells md, int at) {
        // Seven parsed date cells as a JSON array, `null` when absent.
        if (emon.Port.CellsAt(md, at) < 0) {
            emon.Port.TextAscii(t, "null");
            return 0;
        }
        int k = 0;
        emon.Port.TextAscii(t, "[");
        while (k < 7) {
            if (k > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextI32(t, emon.Port.CellsAt(md, at + k));
            k += 1;
        }
        emon.Port.TextAscii(t, "]");
        return 0;
    }
    public static int PmDump(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells md, emon.Port.Cells xm, emon.Port.Cells ol, emon.Port.Cells lb, emon.Port.Cells nd, emon.Port.Cells pg, emon.Port.Cells sc) {
        // The catalogue extras as one canonical JSON object: `lang`, `version`, `info`, the
        // catalog's flags, `xmp` (its identification and every property row), `outlines` (rows,
        // pre-order), `labels` (the ranges and the label of every page, built in the scratch
        // `sc`) and `dests`. Not a
        // public contract; what the laws and the oracle compare.
        int nx = emon.Port.CellsLen(xm) / XmStride;
        int no = emon.Port.CellsLen(ol) / OlStride;
        int nlb = emon.Port.CellsLen(lb) / LbStride;
        int ndd = emon.Port.CellsLen(nd) / NdStride;
        int npg = Pdfdoc.PdPgCount(pg);
        int i = 0;
        int k = 0;
        int ln = 0;
        int at = 0;
        emon.Port.TextAscii(t, "{\"lang\":");
        PmJRun(t, txt, md, 0);
        emon.Port.TextAscii(t, ",\"version\":");
        PmJRun(t, txt, md, 50);
        emon.Port.TextAscii(t, ",\"info\":{\"present\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 34));
        emon.Port.TextAscii(t, ",\"title\":");
        PmJRun(t, txt, md, 2);
        emon.Port.TextAscii(t, ",\"author\":");
        PmJRun(t, txt, md, 4);
        emon.Port.TextAscii(t, ",\"subject\":");
        PmJRun(t, txt, md, 6);
        emon.Port.TextAscii(t, ",\"keywords\":");
        PmJRun(t, txt, md, 8);
        emon.Port.TextAscii(t, ",\"creator\":");
        PmJRun(t, txt, md, 10);
        emon.Port.TextAscii(t, ",\"producer\":");
        PmJRun(t, txt, md, 12);
        emon.Port.TextAscii(t, ",\"created\":");
        PmJRun(t, txt, md, 14);
        emon.Port.TextAscii(t, ",\"createdParsed\":");
        PmJDate(t, md, 20);
        emon.Port.TextAscii(t, ",\"modified\":");
        PmJRun(t, txt, md, 16);
        emon.Port.TextAscii(t, ",\"modifiedParsed\":");
        PmJDate(t, md, 27);
        emon.Port.TextAscii(t, ",\"trapped\":");
        PmJRun(t, txt, md, 18);
        emon.Port.TextAscii(t, "},\"marked\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 35));
        emon.Port.TextAscii(t, ",\"structTree\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 36));
        emon.Port.TextAscii(t, ",\"acroForm\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 37));
        emon.Port.TextAscii(t, ",\"needAppearances\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 38));
        emon.Port.TextAscii(t, ",\"sigFlags\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 39));
        emon.Port.TextAscii(t, ",\"xfa\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 53));
        emon.Port.TextAscii(t, ",\"displayDocTitle\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 40));
        emon.Port.TextAscii(t, ",\"perms\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 52));
        emon.Port.TextAscii(t, ",\"xmp\":{\"state\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 41));
        emon.Port.TextAscii(t, ",\"pdfuaPart\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 42));
        emon.Port.TextAscii(t, ",\"pdfuaRev\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 59));
        emon.Port.TextAscii(t, ",\"pdfaPart\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(md, 43));
        emon.Port.TextAscii(t, ",\"pdfaConformance\":");
        PmJRun(t, txt, md, 44);
        emon.Port.TextAscii(t, ",\"props\":[");
        while (i < nx) {
            at = i * XmStride;
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextAscii(t, "{\"name\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(xm, at), emon.Port.CellsAt(xm, at + 1));
            emon.Port.TextAscii(t, ",\"kind\":\"");
            XmkEmitName(t, emon.Port.CellsAt(xm, at + 2));
            emon.Port.TextAscii(t, "\",\"value\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(xm, at + 3), emon.Port.CellsAt(xm, at + 4));
            if (emon.Port.CellsAt(xm, at + 5) >= 0) {
                emon.Port.TextAscii(t, ",\"lang\":");
                Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(xm, at + 5), emon.Port.CellsAt(xm, at + 6));
            }
            if (emon.Port.CellsAt(xm, at + 7) != 0) {
                emon.Port.TextAscii(t, ",\"known\":\"");
                XkEmitName(t, emon.Port.CellsAt(xm, at + 7));
                emon.Port.TextAscii(t, "\"");
            }
            emon.Port.TextAscii(t, "}");
            i += 1;
        }
        emon.Port.TextAscii(t, "]},\"outlines\":[");
        i = 0;
        while (i < no) {
            at = i * OlStride;
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextAscii(t, "{\"depth\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at));
            emon.Port.TextAscii(t, ",\"parent\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 1));
            emon.Port.TextAscii(t, ",\"children\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 2));
            emon.Port.TextAscii(t, ",\"subtree\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 3));
            emon.Port.TextAscii(t, ",\"obj\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 4));
            emon.Port.TextAscii(t, ",\"title\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(ol, at + 5), emon.Port.CellsAt(ol, at + 6));
            emon.Port.TextAscii(t, ",\"count\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 7));
            emon.Port.TextAscii(t, ",\"flags\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 8));
            if (emon.Port.CellsAt(ol, at + 9) >= 0) {
                emon.Port.TextAscii(t, ",\"color\":");
                emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 9));
            }
            if (emon.Port.CellsAt(ol, at + 10) != 0) {
                emon.Port.TextAscii(t, ",\"action\":\"");
                Pdfannot.AnActEmitName(t, emon.Port.CellsAt(ol, at + 10));
                emon.Port.TextAscii(t, "\"");
            }
            if (emon.Port.CellsAt(ol, at + 11) >= 0) {
                emon.Port.TextAscii(t, ",\"target\":");
                Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(ol, at + 11), emon.Port.CellsAt(ol, at + 12));
            }
            if (Pdfx.PxDestPresent(ol, at + 13) == 1) {
                emon.Port.TextAscii(t, ",\"dest\":");
                Pdfx.PxJsonDest(t, txt, ol, at + 13);
            }
            emon.Port.TextAscii(t, ",\"bits\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(ol, at + 21));
            emon.Port.TextAscii(t, "}");
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"labels\":{\"ranges\":[");
        i = 0;
        while (i < nlb) {
            at = i * LbStride;
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextAscii(t, "{\"page\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(lb, at));
            emon.Port.TextAscii(t, ",\"style\":\"");
            LsEmitName(t, emon.Port.CellsAt(lb, at + 1));
            emon.Port.TextAscii(t, "\",\"prefix\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(lb, at + 2), emon.Port.CellsAt(lb, at + 3));
            emon.Port.TextAscii(t, ",\"start\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(lb, at + 4));
            emon.Port.TextAscii(t, ",\"end\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(lb, at + 5));
            emon.Port.TextAscii(t, ",\"bits\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(lb, at + 6));
            emon.Port.TextAscii(t, "}");
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"pages\":[");
        i = 0;
        while (i < npg) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.CellsDrop(sc, 0);
            ln = PmLabelCells(txt, lb, i, sc);
            if (ln >= 0) {
                emon.Port.TextAscii(t, "\"");
                k = 0;
                while (k < ln) {
                    Pdfx.PxJsonEscCp(t, emon.Port.CellsAt(sc, k));
                    k += 1;
                }
                emon.Port.TextAscii(t, "\"");
            } else {
                emon.Port.TextAscii(t, "null");
            }
            i += 1;
        }
        emon.Port.TextAscii(t, "]},\"dests\":[");
        i = 0;
        while (i < ndd) {
            at = i * NdStride;
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextAscii(t, "{\"name\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(nd, at), emon.Port.CellsAt(nd, at + 1));
            emon.Port.TextAscii(t, ",\"dest\":");
            Pdfx.PxJsonDest(t, txt, nd, at + 2);
            emon.Port.TextAscii(t, "}");
            i += 1;
        }
        emon.Port.TextAscii(t, "]}");
        return 0;
    }
}
